// Suite spec 0019, AC-27: draws the ///L mark (logo A: gold on navy, R35LogoPlaces) as the PNG
// the code emails embed by CID, and writes it as base64 into src/auth/codes/email-logo.ts.
// Run: node scripts/email-logo.mjs  (no dependencies; commit the generated file)
import { writeFileSync } from 'node:fs';
import { deflateSync } from 'node:zlib';

// The mark's polygons in its 330 x 185 viewBox (the portal's LogoMark)
const POLYGONS = [
  [[82, 0], [144, 0], [66, 183], [4, 183]],
  [[177, 0], [240, 0], [162, 183], [100, 183]],
  [[265, 0], [328, 0], [268, 140], [328, 140], [328, 183], [187, 183]],
];
const NAVY = [0x0f, 0x14, 0x45];
const GOLD = [0xe8, 0xb8, 0x00];
// Shown at 36 x 20 in the email; drawn at 3x for sharp screens
const WIDTH = 108;
const HEIGHT = 61;
const SAMPLES = 4;

function inside([x, y], polygon) {
  let hit = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const [xi, yi] = polygon[i];
    const [xj, yj] = polygon[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) {
      hit = !hit;
    }
  }
  return hit;
}

const scale = 330 / WIDTH;
const rows = [];
for (let py = 0; py < HEIGHT; py++) {
  const row = [0]; // filter: none
  for (let px = 0; px < WIDTH; px++) {
    let covered = 0;
    for (let sy = 0; sy < SAMPLES; sy++) {
      for (let sx = 0; sx < SAMPLES; sx++) {
        const point = [
          (px + (sx + 0.5) / SAMPLES) * scale,
          (py + (sy + 0.5) / SAMPLES) * scale,
        ];
        if (POLYGONS.some((p) => inside(point, p))) covered++;
      }
    }
    const a = covered / (SAMPLES * SAMPLES);
    for (let c = 0; c < 3; c++) {
      row.push(Math.round(NAVY[c] + (GOLD[c] - NAVY[c]) * a));
    }
  }
  rows.push(Buffer.from(row));
}

const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}
const header = Buffer.alloc(13);
header.writeUInt32BE(WIDTH, 0);
header.writeUInt32BE(HEIGHT, 4);
header[8] = 8; // bit depth
header[9] = 2; // truecolour, no alpha: Outlook draws it the same everywhere
const png = Buffer.concat([
  Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
  chunk('IHDR', header),
  chunk('IDAT', deflateSync(Buffer.concat(rows), { level: 9 })),
  chunk('IEND', Buffer.alloc(0)),
]);

const out = `// Generated by scripts/email-logo.mjs (suite spec 0019, AC-27). Do not edit by hand.
// The ///L mark, gold on navy (logo A), ${WIDTH} x ${HEIGHT} px, shown at 36 x 20 in the code emails.

export const EMAIL_LOGO_WIDTH = 36;
export const EMAIL_LOGO_HEIGHT = 20;

export const EMAIL_LOGO_PNG_BASE64 =
  '${png.toString('base64')}';
`;
writeFileSync(new URL('../src/auth/codes/email-logo.ts', import.meta.url), out);
console.log(`email-logo.ts written (${png.length} bytes of PNG)`);
